(function(){
  const icon=name=>({search:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path></svg>',bag:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8h14l-1 12H6L5 8Z"></path><path d="M9 9V6a3 3 0 0 1 6 0v3"></path></svg>',sun:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"></circle><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"></path></svg>',menu:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"></path></svg>',close:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"></path></svg>'})[name];
  const nav=[['Home','index.html'],['About','about.html'],['Products','products.html'],['Ingredients','ingredients.html'],['Consultation','consultation.html'],['Certifications','certifications.html'],['Contact','contact.html']];
  function shell(){const page=document.body.dataset.page||'';const header=document.querySelector('[data-site-header]');if(header)header.innerHTML=`<a class="skip-link" href="#main">Skip to content</a><div class="announcement">Thoughtful botanical goods · Orders currently fulfilled by request</div><header class="site-header"><a class="brand" href="index.html" aria-label="VanaVeda home"><img class="brand-light" src="../assets/brand/logo-dark.svg" alt="VanaVeda"><img class="brand-dark" src="../assets/brand/logo-light.svg" alt="VanaVeda"></a><nav class="desktop-nav" aria-label="Primary">${nav.map(([label,href])=>`<a href="${href}"${page===label.toLowerCase()?' aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="header-tools"><button class="icon-button" data-open-search aria-label="Search">${icon('search')}</button><button class="bag-button" data-open-cart aria-label="Open bag">${icon('bag')}<span>Bag</span><b data-cart-count hidden>0</b></button><button class="icon-button" data-theme-toggle aria-label="Toggle color theme">${icon('sun')}</button><button class="direction-button" data-dir-toggle aria-label="Toggle text direction">RTL</button><button class="icon-button menu-button" data-menu-toggle aria-label="Open menu">${icon('menu')}</button></div></header><div class="mobile-panel" data-mobile-panel><div class="mobile-panel__top"><span>Menu</span><button class="icon-button" data-menu-toggle aria-label="Close menu">${icon('close')}</button></div><nav aria-label="Mobile">${nav.map(([label,href])=>`<a href="${href}">${label}</a>`).join('')}<a href="cart.html">Bag</a><a href="home2.html">Editorial home</a></nav></div>`;
    const footer=document.querySelector('[data-site-footer]');if(footer)footer.innerHTML=`<footer class="footer"><div class="footer__main"><div><a class="footer-brand" href="index.html"><img src="../assets/brand/logo-light.svg" alt="VanaVeda"></a><p>Botanical goods for considered daily rituals. Clear ingredients, practical directions, no miracle language.</p></div><div><h2>Shop</h2><a href="products.html">All products</a><a href="ingredients.html">Ingredient glossary</a><a href="cart.html">Your bag</a><a href="home2.html">Editorial home</a></div><div><h2>Help</h2><a href="faq.html">FAQ</a><a href="shipping-returns.html">Shipping & returns</a><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a></div><div><h2>Stay close</h2><p>Occasional notes on new blends and considered routines.</p><form data-local-form class="newsletter"><label class="sr-only" for="footer-email">Email address</label><input id="footer-email" type="email" placeholder="Email address" required><button type="submit" aria-label="Join mailing list">→</button><small data-form-status aria-live="polite"></small></form></div></div><div class="footer__bottom"><span>© 2026 VanaVeda</span><span>Frontend storefront · commerce connection pending</span></div></footer>`;
    document.body.insertAdjacentHTML('beforeend',`<div class="drawer-backdrop" data-cart-backdrop></div><aside class="cart-drawer" data-cart-drawer aria-label="Shopping bag"><div class="drawer-head"><h2>Your bag</h2><button class="icon-button" data-close-cart aria-label="Close bag">${icon('close')}</button></div><div class="mini-cart-items" data-mini-cart-items></div><div class="drawer-foot" data-mini-cart-footer hidden><div><span>Subtotal</span><strong data-mini-subtotal></strong></div><a class="button button--full" href="cart.html">View bag</a></div></aside><div class="search-overlay" data-search-overlay><div class="search-dialog" role="dialog" aria-modal="true" aria-label="Search products"><button class="icon-button search-close" data-close-search aria-label="Close search">${icon('close')}</button><label for="global-search">Search the store</label><div class="search-field">${icon('search')}<input id="global-search" data-global-search type="search" placeholder="Try tulsi, rose, tea…" autocomplete="off"></div><div class="search-results" data-search-results></div></div></div>`);
  }
  function interactions(){document.addEventListener('click',e=>{if(e.target.closest('[data-menu-toggle]')){document.querySelector('[data-mobile-panel]').classList.toggle('is-open');document.body.classList.toggle('no-scroll');}if(e.target.closest('[data-theme-toggle]')){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('vanaveda-theme',next);}if(e.target.closest('[data-dir-toggle]')){const next=document.documentElement.dir==='rtl'?'ltr':'rtl';document.documentElement.dir=next;localStorage.setItem('vanaveda-dir',next);document.querySelector('[data-dir-toggle]').textContent=next==='rtl'?'LTR':'RTL';}if(e.target.closest('[data-open-search]'))openSearch();if(e.target.closest('[data-close-search]')||e.target===document.querySelector('[data-search-overlay]'))closeSearch();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeSearch();document.querySelector('[data-mobile-panel]')?.classList.remove('is-open');}});const search=document.querySelector('[data-global-search]');search?.addEventListener('input',()=>renderSearch(search.value));const hero=document.querySelector('[data-hero-scene]');if(hero&&!matchMedia('(prefers-reduced-motion: reduce)').matches){hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;hero.style.setProperty('--rx',`${-y*8}deg`);hero.style.setProperty('--ry',`${x*10}deg`);});hero.addEventListener('pointerleave',()=>{hero.style.setProperty('--rx','0deg');hero.style.setProperty('--ry','0deg');});}setupReveal();}
  function openSearch(){const el=document.querySelector('[data-search-overlay]');el.classList.add('is-open');document.body.classList.add('no-scroll');setTimeout(()=>document.querySelector('[data-global-search]').focus(),50);renderSearch('');}
  function closeSearch(){document.querySelector('[data-search-overlay]')?.classList.remove('is-open');document.body.classList.remove('no-scroll');}
  function renderSearch(value){const q=value.trim().toLowerCase();const rows=(window.VANAVEDA_PRODUCTS||[]).filter(p=>!q||`${p.name} ${p.category} ${p.ingredients.join(' ')}`.toLowerCase().includes(q)).slice(0,6);const el=document.querySelector('[data-search-results]');el.innerHTML=rows.length?rows.map(p=>`<a href="product-details.html?id=${p.id}"><img src="../assets/images/${p.image}" alt=""><span><small>${p.category}</small><strong>${p.name}</strong></span><b>${VANAVEDA_FORMAT_PRICE(p.price)}</b></a>`).join(''):`<p class="search-empty">No matching products. Try a category or ingredient.</p>`;}
  function setupReveal(){const els=document.querySelectorAll('[data-reveal]:not(.is-visible)');if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){els.forEach(el=>el.classList.add('is-visible'));return;}const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');io.unobserve(entry.target);}}),{threshold:.08,rootMargin:'0px 0px -40px'});els.forEach(el=>io.observe(el));setTimeout(()=>els.forEach(el=>{el.classList.add('is-visible');io.unobserve(el);}),900);}
  document.addEventListener('vanaveda:rerender',setupReveal);document.addEventListener('DOMContentLoaded',()=>{shell();interactions();if(document.documentElement.dir==='rtl')document.querySelector('[data-dir-toggle]').textContent='LTR';});
})();
